/// <summary>
/// Extension of class <c>GUPAttributeBasedPricingDataManager</c>
/// to overwrite default price from item base price version MPJ-28015
/// </summary>
[ExtensionOf(classStr(GUPAttributeBasedPricingDataManager))]
public final class METGUPAttributeBasedPricingDataManager_Extension
{
}

Method.Source:
    /// <summary>
    /// Override free item price
    /// </summary>
    /// <param name = "_freeItemLine">Free item line</param>
    /// <param name = "_toUnitOfMeasureSymbol">Unit of measure to</param>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_price">Default price</param>
    /// <param name = "_fromUnitOfMeasureSymbol">Unit of measure from</param>
    /// <param name = "_priceUnit">Price unit</param>
    /// <param name = "_markup">Markup</param>
    /// <returns></returns>
    public Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine ConvertToFreeItemLine(
        GUPFreeItemLine _freeItemLine,
        UnitOfMeasureSymbol _toUnitOfMeasureSymbol,
        ItemId _itemId,
        Price _price,
        UnitOfMeasureSymbol _fromUnitOfMeasureSymbol,
        PriceUnit _priceUnit,
        InventPriceMarkup _markup)
    {
        InventSiteId siteId = InventDim::find(_freeItemLine.InventDimId).InventSiteId;
        
        Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine crtFreeItemLine = next ConvertToFreeItemLine(_freeItemLine, _toUnitOfMeasureSymbol, _itemId, _price, _fromUnitOfMeasureSymbol, _priceUnit, _markup);

        GUPItemBasePrice    itemBasePrice;
       
        InventDim inventDim;
        inventDim.InventSiteId = siteId;
        inventDim = InventDim::findDim(inventDim);

        itemBasePrice = GUPItemBasePrice::findCurrent(_itemId, GUPBasePriceType::BasePriceInventoryCost, inventDim.inventDimId);


        if(itemBasePrice)
        {
            PriceConvertFactory priceConvertFactory = PriceConvertFactory::newItemPrice(
                _itemId,
                itemBasePrice.UnitId,
                itemBasePrice.Price,
                _priceUnit,
                _markup,
                1,
                Ledger::accountingCurrency(CompanyInfo::current()));

            priceConvertFactory.parmNewUnitId(_toUnitOfMeasureSymbol);
            PriceConvert priceConvert = priceConvertFactory.priceConvert();
            crtFreeItemLine.Price = priceConvert.parmPrice();
        }

        return crtFreeItemLine;
    }
